import{z as B,x as A,o as e,c as D,q as n,j as t,D as E,d as s,s as o,S as r}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"Flynn 分类","description":"","frontmatter":{"title":"Flynn 分类","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/flynn-taxonomy.md","filePath":"cs/flynn-taxonomy.md","lastUpdated":1791413859000}'),i={name:"cs/flynn-taxonomy.md"};function S(I,a,p,d,M,c){const l=A("Mermaid");return e(),D("div",null,[a[2]||(a[2]=n('<h1 id="flynn-分类" tabindex="-1">Flynn 分类 <a class="header-anchor" href="#flynn-分类" aria-label="Permalink to &quot;Flynn 分类&quot;">​</a></h1><div class="epigraph"><p>按指令流与数据流的份数把机器分成 SISD、SIMD、MISD、MIMD；它不管缓存协议，只管「同时在飞的是一条指令还是很多」。 </p><footer>—— 据 Flynn, Very High-Speed Computing Systems, Proceedings of the IEEE, 1966 整理</footer></div><p><a href="/cs/fence-cost">上一课</a> 收束单核顺序与一致性进阶。单核 ILP 再挖也是一条指令流。<a href="/cs/superscalar-issue">超标量</a> 每拍多条，仍是同一 PC 家族。本课不重讲 fence drain。缺口是 <strong>Flynn 的四格：用指令流 × 数据流给后面的 VLIW、向量、SIMT、多核一个共同坐标系。</strong></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>乱序核、向量机、GPU、多 socket 在文献里都叫「并行」， intern 容易把发射宽度与核数相加。缺口不是再加一种 cache 态，而是<strong>先分箱：同一时刻有几条指令流、每条指令流操作几份数据。</strong> 后续课只在格子里走，不把 GPU 写成「很大的超标量」。</p><p><span class="marginnote">SISD：经典单核。SIMD：一条指令、向量数据。MISD：少见（某些流水脉动可硬塞）。MIMD：多核、多线程各有 PC。</span></p><p><span class="marginnote">用厨房类比这四格：SISD 是一个厨师顺序做一道菜；SIMD 是一个厨师对 8 口锅做同一个「翻炒」动作——动作一条、食材八份；MIMD 是 8 个厨师各做各的菜、各有各的菜谱进度；MISD 像多道质检工序依次检查同一份菜——动作多条、食材一份。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>SISD：本课程前两单元的核。SIMD：后课向量 lane、以及 ISA 对照里的 <a href="/cs/simd-extensions">SIMD 扩展</a>——一条 opcode，多条 ALU。MIMD：后课多 socket、big.LITTLE。SIMT 是 SIMD 的控制实现：硬件上很多 lane 共享一个 PC，遇分支再发散，不是第四个 Flynn 类，下一课之后才拆。</p>',9)),(e(),t(r,null,{default:E(()=>[o(l,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E6%8C%87%E4%BB%A4%E6%B5%81%20%C3%97%20%E6%95%B0%E6%8D%AE%E6%B5%81%22%5D%20--%3E%20SISD%5B%22SISD%20%E5%8D%95%E6%B5%81%E5%8D%95%E6%95%B0%E6%8D%AE%22%5D%0A%20%20F%20--%3E%20SIMD%5B%22SIMD%20%E5%8D%95%E6%B5%81%E5%A4%9A%E6%95%B0%E6%8D%AE%22%5D%0A%20%20F%20--%3E%20MIMD%5B%22MIMD%20%E5%A4%9A%E6%B5%81%E5%A4%9A%E6%95%B0%E6%8D%AE%22%5D%0A%20%20SIMD%20--%3E%20SIMT%5B%22SIMT%EF%BC%9A%E5%85%B1%E4%BA%AB%20PC%20%E7%9A%84%20SIMD%20%E5%AE%9E%E7%8E%B0%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p><a href="/cs/cpi-amdahl">阿姆达尔</a> 在 MIMD 上变成「串行段限制加速比」；SIMD 上变成「向量化比例」。二者不要混用同一个 \\(f\\)。一致性只出现在 MIMD（及 SIMD 核之间的共享内存），SISD 无需 <a href="/cs/mesi-protocol">MESI</a>。</p><p><span class="marginnote">数字实例看清两个 \\(f\\) 的差别：串行段占 10% 时，8 核 MIMD 加速上限是 \\(1/(0.1+0.9/8)\\approx 4.7\\) 倍；8 lane SIMD 上向量化比例 90% 时上限同样是约 4.7 倍——公式同形，但前一个 \\(f\\) 是「必须顺序执行的代码占比」，后一个是「能改写成向量指令的代码占比」，来源完全不同。</span></p><p><span class="marginnote">初学者容易把 GPU 的「几千个核」直接归入 MIMD。实际上 SIMT 下一个 warp 的 32 条 lane 共享同一个程序计数器，同一拍执行的是同一条指令，只有遇分支才分道——所以它是 SIMD 的控制包装，而不是第四个 Flynn 类。</span></p><p>本课声明边界：大模型栏的张量并行不是本栏的 Flynn 练习；这里只为 CPU/GPU/DSA 硬件分型。</p>',5)),(e(),t(r,null,{default:E(()=>[o(l,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E4%B8%80%E4%B8%AA%20warp%3A32%20%E6%9D%A1%20lane%20%E5%85%B1%E4%BA%AB%E5%90%8C%E4%B8%80%E4%B8%AA%20PC%22%5D%20--%3E%20BR%7B%22%E6%89%A7%E8%A1%8C%E5%88%B0%20if%20%E5%88%86%E6%94%AF%22%7D%0A%20%20BR%20--%20%2216%20%E6%9D%A1%20lane%20%E6%9D%A1%E4%BB%B6%E4%B8%BA%E7%9C%9F%22%20--%3E%20T%5B%22%E7%9C%9F%E8%B7%AF%E5%BE%84%3A%E8%BF%99%2016%20%E6%9D%A1%20lane%20%E5%B9%B2%E6%B4%BB%22%5D%0A%20%20BR%20--%20%22%E5%8F%A6%2016%20%E6%9D%A1%E6%9D%A1%E4%BB%B6%E4%B8%BA%E5%81%87%22%20--%3E%20F%5B%22%E5%81%87%E8%B7%AF%E5%BE%84%3A%E9%82%A3%2016%20%E6%9D%A1%20lane%20%E5%B9%B2%E6%B4%BB%22%5D%0A%20%20T%20--%3E%20SER%5B%22%E4%B8%A4%E6%AE%B5%E5%8F%AA%E8%83%BD%E4%B8%B2%E8%A1%8C%E6%89%A7%E8%A1%8C%2C%E6%AF%8F%E6%AE%B5%E5%8F%A6%E4%B8%80%E5%8D%8A%20lane%20%E7%A9%BA%E8%BD%AC%22%5D%0A%20%20F%20--%3E%20SER%0A%20%20SER%20--%3E%20J%5B%22%E6%B1%87%E5%90%88%2C%E5%9B%9E%E5%88%B0%E5%90%8C%E4%B8%80%E4%B8%AA%20PC%20%E7%BB%A7%E7%BB%AD%E8%B5%B0%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=n('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 VLIW 的编译器打包写完，下一课。也不把数据流机当成第五类 Flynn——Dennis 的数据流是另一轴，再下一课。MISD 不展开。</p><p>后课默认：谈到并行先报 Flynn 格子。把多条独立操作塞进一个长指令字，是 VLIW/EPIC。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Flynn 用指令流与数据流分 SISD/SIMD/MIMD。</li><li>SIMT 是 SIMD 的控制包装，不是新格子。</li><li>VLIW 把并行打包交给编译器，下一课。</li><li>出处：Flynn, <em>IEEE Proc.</em>, 1966。</li></ul>',5))])}const _=B(i,[["render",S]]);export{f as __pageData,_ as default};
